    correction: [{"quoi":"المبدأ","math":"نملأ كلّ المراكز، من الأوّل إلى الأخير"},{"quoi":"عدد الإختيارات في كل مركز","math":"المركز الأوّل 7، ثمّ 6، و هكذا إلى غاية 1"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">7 × 6 × 5 × 4 × 3 × 2 × 1 = 5040</span>"},{"quoi":"النتيجة","math":"عدد الترتيبات الكاملة هو 5040"}],
