    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">8<sup>235</sup> = 2<sup>705</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>708</sup> + n × 2<sup>705</sup> = 2<sup>705</sup>(2<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">28 = 4 × 7</span>"},{"quoi":"العامل 4 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>705</sup> = 2<sup>2</sup> × 2<sup>703</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2<sup>3</sup> + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2<sup>3</sup> = 8</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 50 بحيث يقبل <span dir=\"ltr\" class=\"expr\">8 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 6 ؛ 13 ؛ 20 ؛ 27 ؛ 34 ؛ 41 ؛ 48</span>"}],
